import{_ as t,o,c as a,ag as i}from"./chunks/framework.DMVuHR7L.js";const s="/web-logcat/staging/docs/assets/shell-default.DFTyoMwv.png",p=JSON.parse('{"title":"Shell","description":"","frontmatter":{},"headers":[],"relativePath":"features/shell.md","filePath":"features/shell.md","lastUpdated":1778206888000}'),r={name:"features/shell.md"};function l(d,e,n,c,h,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to &quot;Shell&quot;">​</a></h1><p>The Shell widget is an interactive ADB shell tied to one tile. Each tile owns its own channel — opening two Shell tiles gives you two independent sessions, with separate working directories and history.</p><p><img src="'+s+'" alt="Shell tile"></p><h2 id="running-commands" tabindex="-1">Running commands <a class="header-anchor" href="#running-commands" aria-label="Permalink to &quot;Running commands&quot;">​</a></h2><p>Type a command at the prompt and hit <code>Enter</code>. The output streams into the scrollback as it arrives, the same way <code>adb shell</code> would render it in a terminal.</p><p>The shell is a regular interactive <code>sh</code> channel on the device, so anything the device&#39;s shell understands works — pipes, <code>grep</code>, <code>find</code>, multi-line commands, etc. There is no remote <code>bash</code> unless your device ships one.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li><code>↑</code> / <code>↓</code> walks history backwards / forwards.</li><li>History is per-tile and persists across reloads.</li><li><code>Ctrl+L</code> clears the visible scrollback (history is preserved).</li></ul><h2 id="working-directory" tabindex="-1">Working directory <a class="header-anchor" href="#working-directory" aria-label="Permalink to &quot;Working directory&quot;">​</a></h2><p>The first prompt drops you in the device&#39;s home (commonly <code>/sdcard</code>). Use <code>cd</code> like normal — the prompt updates to reflect the new location. The default starting path is configurable in the per-widget settings modal (the cog in the header).</p><h2 id="built-ins" tabindex="-1">Built-ins <a class="header-anchor" href="#built-ins" aria-label="Permalink to &quot;Built-ins&quot;">​</a></h2><p>The widget recognises a small set of host-side built-ins that don&#39;t go over the wire:</p><ul><li><code>clear</code> (alias <code>cls</code>) — equivalent to <code>Ctrl+L</code>.</li><li><code>help</code> — list built-ins. <code>help &lt;name&gt;</code> prints details for one.</li><li><code>exit</code> — close the channel. The next command reopens it automatically.</li></ul><p>Everything else is forwarded to the device.</p><h2 id="simulator-behaviour" tabindex="-1">Simulator behaviour <a class="header-anchor" href="#simulator-behaviour" aria-label="Permalink to &quot;Simulator behaviour&quot;">​</a></h2><p>When you&#39;re connected to the <a href="./simulator">simulated stream</a>, the Shell widget drops you into an in-memory fake (<code>lib/shellSim.ts</code>) that recognises the most common commands — <code>pwd</code>, <code>ls</code>, <code>cat</code>, <code>whoami</code>, <code>uname</code> — and simulated filesystem paths under <code>/sdcard/</code>. Use it to poke around the widget without a phone.</p><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><ul><li><strong>Home directory.</strong> Override the starting <code>cd</code> when the tile mounts.</li><li><strong>Font size.</strong> Bumps the shell text without affecting the rest of the dashboard.</li></ul><p>Changes persist per-tile via <code>localStorage</code>.</p>',19)])])}const g=t(r,[["render",l]]);export{p as __pageData,g as default};
